window.KITCHEN_RECIPES = [{"id": "thin-pancakes", "title": "Thin pancakes & maple syrup", "category": "Breakfast", "prep": 10, "cook": 20, "rest": 20, "serves": 4, "ingredients": [{"q": 100, "unit": "g", "name": "plain flour"}, {"q": 2, "unit": "", "name": "medium eggs"}, {"q": 300, "unit": "ml", "name": "milk"}, {"q": 1, "unit": "tbsp", "name": "melted butter, plus a little for the pan"}, {"q": 1, "unit": "pinch", "name": "salt"}, {"q": 4, "unit": "tbsp", "name": "maple syrup, to serve"}], "steps": [{"title": "Mix the batter", "time": 5, "text": "Whisk flour and salt with the eggs and half the milk until smooth. Gradually whisk in the remaining milk and melted butter. The batter should pour like single cream."}, {"title": "Rest", "time": 20, "text": "Cover and leave for 20 minutes. Whisk briefly before cooking. This batch makes about 8 thin pancakes in a 20 cm pan."}, {"title": "Heat the pan", "time": 2, "text": "Warm a non-stick frying pan over medium heat. Wipe with a little butter; it should gently sizzle, not smoke."}, {"title": "Cook in batches", "time": 2, "text": "Pour in about 50–60 ml batter and immediately tilt to coat. Cook 60–90 seconds until the top loses its wet shine and the edges lift; flip and cook 30–45 seconds. Repeat, adjusting heat if they darken too fast."}, {"title": "Serve", "time": 0, "text": "Fold or roll and drizzle with maple syrup. Keep cooked pancakes covered on a warm plate while finishing the batch."}], "science": "Resting lets flour hydrate and reduces resistance from gluten, helping the batter spread thinly. Egg proteins set and starch thickens as the pancake heats.", "fix": "Tearing: give the first side longer to set. Thick pancakes: add milk a tablespoon at a time. Dark outside but wet inside: lower the heat.", "tags": ["Sweet", "Easy", "Warm", "British"], "lesson": "gluten", "foodTypes": [], "equipment": "Kitchen scales, bowl, whisk, 20 cm non-stick frying pan, ladle and spatula."}, {"id": "shakshuka", "title": "Tomato & pepper baked eggs", "category": "Breakfast", "prep": 10, "cook": 25, "rest": 0, "serves": 2, "ingredients": [{"q": 1, "unit": "tbsp", "name": "olive oil"}, {"q": 1, "unit": "", "name": "onion, finely sliced"}, {"q": 1, "unit": "", "name": "red pepper, diced"}, {"q": 2, "unit": "", "name": "garlic cloves, minced"}, {"q": 1, "unit": "tsp", "name": "ground cumin"}, {"q": 0.5, "unit": "tsp", "name": "smoked paprika"}, {"q": 400, "unit": "g", "name": "tinned chopped tomatoes"}, {"q": 4, "unit": "", "name": "eggs"}, {"q": 1, "unit": "pinch", "name": "salt and black pepper"}], "steps": [{"title": "Soften the vegetables", "time": 8, "text": "Warm the oil in a wide lidded pan over medium heat. Add onion and pepper; stir regularly until soft, lowering heat if the onion catches."}, {"title": "Bloom the spices", "time": 1, "text": "Add garlic, cumin and paprika. Stir for 30–60 seconds until fragrant."}, {"title": "Reduce the sauce", "time": 10, "text": "Add tomatoes and seasoning. Simmer uncovered over medium-low heat, stirring occasionally, until thick enough to hold small wells."}, {"title": "Set the eggs", "time": 7, "text": "Make four wells and crack an egg into each. Cover and cook gently for 6–9 minutes, until the whites are set. Continue until yolks are firm if required. Use British Lion-marked hen eggs if choosing runny yolks; follow individual dietary advice."}], "science": "Evaporating water first concentrates the tomato flavour and prevents the eggs from floating in a watery sauce. A lid traps steam to cook the egg tops.", "fix": "Watery sauce: reduce it before adding eggs. Scorched bottom: use lower heat and a heavy pan.", "tags": ["Savoury", "Easy", "Hot"], "lesson": "reduction", "foodTypes": [], "equipment": "Wide frying pan with a lid, chopping board, knife and spoon."}, {"id": "tomato-pasta", "title": "Garlic tomato & basil pasta", "category": "Dinner", "prep": 10, "cook": 25, "rest": 0, "serves": 2, "ingredients": [{"q": 180, "unit": "g", "name": "dried pasta"}, {"q": 1, "unit": "tbsp", "name": "olive oil"}, {"q": 3, "unit": "", "name": "garlic cloves, thinly sliced"}, {"q": 400, "unit": "g", "name": "tinned chopped tomatoes"}, {"q": 1, "unit": "tsp", "name": "tomato purée"}, {"q": 6, "unit": "", "name": "basil leaves, torn"}, {"q": 20, "unit": "g", "name": "Parmesan, optional"}, {"q": 1, "unit": "pinch", "name": "salt and pepper"}], "steps": [{"title": "Start the sauce", "time": 2, "text": "Warm oil over medium-low heat. Add garlic and stir 30–60 seconds until fragrant, without browning it. Stir in tomato purée for another minute."}, {"title": "Simmer", "time": 20, "text": "Add tomatoes. Simmer uncovered for 15–20 minutes, stirring now and then, until the sauce thickens. Season to taste."}, {"title": "Boil the pasta", "time": 10, "text": "During the last part of the simmer, cook pasta in boiling salted water according to its packet, usually 8–12 minutes. Taste for a firm centre. Reserve a mug of pasta water before draining."}, {"title": "Bring it together", "time": 2, "text": "Toss pasta with sauce over low heat for 1–2 minutes. Add reserved water a tablespoon at a time until glossy. Stir in basil and finish with Parmesan if using."}], "science": "Pasta water contains dispersed starch. Tossing it with the sauce helps the watery and oily components cling to the pasta.", "fix": "Too thick: add pasta water gradually. Too sharp: simmer a little longer, then balance with a little olive oil; do not automatically add lots of sugar.", "tags": ["Italian", "Easy", "Hot", "Savoury", "Saucy"], "lesson": "emulsions", "foodTypes": ["Pasta & Noodles"]}, {"id": "lemon-chicken", "title": "Lemon, garlic & paprika chicken thighs", "category": "Dinner", "prep": 15, "cook": 35, "rest": 5, "serves": 4, "ingredients": [{"q": 800, "unit": "g", "name": "boneless skinless chicken thighs"}, {"q": 2, "unit": "tbsp", "name": "olive oil"}, {"q": 1, "unit": "", "name": "lemon, zest and juice"}, {"q": 3, "unit": "", "name": "garlic cloves, crushed"}, {"q": 1, "unit": "tsp", "name": "smoked paprika"}, {"q": 1, "unit": "tsp", "name": "dried oregano"}, {"q": 0.5, "unit": "tsp", "name": "salt"}, {"q": 0.25, "unit": "tsp", "name": "black pepper"}], "steps": [{"title": "Prepare safely", "time": 10, "text": "Heat oven to 200°C fan / 220°C conventional. Mix oil, lemon, garlic, paprika, oregano, salt and pepper. Coat the thighs in a bowl. Do not wash raw chicken; wash hands and utensils after handling."}, {"title": "Arrange", "time": 5, "text": "Lay thighs in one layer on a metal roasting tray with space between them. Scrape the marinade over the chicken."}, {"title": "Roast and check", "time": 30, "text": "Roast for 25–35 minutes, turning once around halfway. Check the thickest pieces with a clean probe: 75°C for 30 seconds, or 70°C for 2 minutes. If below this, cook longer and recheck."}, {"title": "Rest", "time": 5, "text": "Rest for 5 minutes before serving. Spoon over the cooked tray juices."}], "science": "Dry heat and room between pieces encourage browning. Lemon adds acidity and flavour; it does not make raw chicken safe.", "fix": "Pale surface: the tray may be crowded or too wet. Use a larger tray next time. Browning is not proof that the centre is cooked.", "tags": ["Easy", "Hot", "Savoury", "Juicy"], "lesson": "browning", "safety": "poultry", "foodTypes": ["Meat"]}, {"id": "roast-potatoes", "title": "Crisp-edged roast potatoes", "category": "Dinner", "prep": 15, "cook": 65, "rest": 5, "serves": 4, "ingredients": [{"q": 1000, "unit": "g", "name": "floury potatoes, peeled"}, {"q": 3, "unit": "tbsp", "name": "rapeseed or olive oil"}, {"q": 1, "unit": "tsp", "name": "salt"}, {"q": 1, "unit": "tsp", "name": "dried rosemary, optional"}], "steps": [{"title": "Heat oven and cut", "time": 10, "text": "Heat oven to 200°C fan / 220°C conventional. Cut potatoes into similar 4–5 cm chunks. Put the oil on a sturdy roasting tray and heat it in the oven for 5 minutes."}, {"title": "Parboil", "time": 10, "text": "Cover potatoes with cold water, bring to the boil, then simmer 8–10 minutes until the outer surface softens but centres still resist a knife."}, {"title": "Drain and roughen", "time": 5, "text": "Drain thoroughly, steam-dry for 5 minutes, then gently shake in the pan to roughen the edges."}, {"title": "Roast", "time": 50, "text": "Carefully transfer to the hot oil, turn to coat and spread out. Roast 45–55 minutes, turning after 25 minutes. Add rosemary for the final 15 minutes. They should be deeply golden with crisp edges and tender centres."}, {"title": "Season", "time": 0, "text": "Sprinkle with salt and serve promptly; covering tightly traps steam and softens the crust."}], "science": "Roughened, softened starch creates more surface area. Drying removes water that would otherwise delay browning.", "fix": "Pale and soft: allow more space and more oven time. Avoid a deep dish that traps steam.", "tags": ["British", "Easy", "Hot", "Savoury", "Crispy"], "lesson": "browning", "foodTypes": ["Vegetables"]}, {"id": "lemon-fish", "title": "Lemon butter baked cod", "category": "Dinner", "prep": 10, "cook": 15, "rest": 0, "serves": 2, "ingredients": [{"q": 300, "unit": "g", "name": "cod fillets, about 2 × 150 g"}, {"q": 20, "unit": "g", "name": "butter"}, {"q": 0.5, "unit": "", "name": "lemon, sliced"}, {"q": 1, "unit": "", "name": "garlic clove, finely grated"}, {"q": 1, "unit": "tbsp", "name": "chopped parsley"}, {"q": 1, "unit": "pinch", "name": "salt and pepper"}], "steps": [{"title": "Prepare", "time": 5, "text": "Heat oven to 180°C fan / 200°C conventional. Pat fish dry and place in a small baking dish. Season lightly."}, {"title": "Add flavour", "time": 5, "text": "Dot with butter mixed with garlic. Add lemon slices."}, {"title": "Bake", "time": 15, "text": "Bake 12–18 minutes depending on thickness. The flesh should be opaque and separate easily into flakes. For a temperature-based check, use 70°C for 2 minutes or an equivalent safe combination; do not rely on the timer alone."}, {"title": "Finish", "time": 0, "text": "Scatter with parsley and spoon over the juices. Serve immediately."}], "science": "Fish muscle proteins set quickly. Extra time after it is cooked forces out moisture, so thickness matters more than weight alone.", "fix": "Dry fish: start checking earlier next time. If the centre remains translucent, return to the oven and recheck.", "tags": ["Easy", "Hot", "Savoury"], "lesson": "proteins", "foodTypes": ["Fish & Seafood"]}, {"id": "chickpea-stew", "title": "Smoky chickpea & spinach stew", "category": "Dinner", "prep": 10, "cook": 25, "rest": 0, "serves": 3, "ingredients": [{"q": 1, "unit": "tbsp", "name": "olive oil"}, {"q": 1, "unit": "", "name": "onion, diced"}, {"q": 2, "unit": "", "name": "garlic cloves, crushed"}, {"q": 1, "unit": "tsp", "name": "smoked paprika"}, {"q": 1, "unit": "tsp", "name": "ground cumin"}, {"q": 400, "unit": "g", "name": "tinned chopped tomatoes"}, {"q": 480, "unit": "g", "name": "cooked chickpeas, drained"}, {"q": 150, "unit": "ml", "name": "vegetable stock"}, {"q": 100, "unit": "g", "name": "spinach"}, {"q": 0.5, "unit": "", "name": "lemon, juice"}], "steps": [{"title": "Soften the onion", "time": 7, "text": "Heat oil over medium heat and cook onion for 6–8 minutes, stirring, until softened."}, {"title": "Add aromatics", "time": 1, "text": "Add garlic and spices. Stir for 30–60 seconds, stopping before the garlic burns."}, {"title": "Simmer", "time": 15, "text": "Add tomatoes, chickpeas and stock. Simmer uncovered 15 minutes, stirring occasionally. Mash a few chickpeas against the pan to thicken."}, {"title": "Finish", "time": 2, "text": "Stir in spinach until wilted, about 2 minutes. Add lemon juice to taste and adjust seasoning."}], "science": "Mashing releases starch and solids into the liquid, thickening it without flour. Acid added at the end lifts the finished flavour.", "fix": "Too thick: add stock in small splashes. Bland: taste for salt and acidity separately.", "tags": ["Easy", "Hot", "Savoury", "Creamy"], "lesson": "starch", "foodTypes": ["Soup & Stew", "Vegetables"]}, {"id": "lentil-dal", "title": "Gentle red lentil dal", "category": "Dinner", "prep": 10, "cook": 30, "rest": 0, "serves": 4, "ingredients": [{"q": 200, "unit": "g", "name": "dried red lentils, rinsed"}, {"q": 1, "unit": "tbsp", "name": "oil"}, {"q": 1, "unit": "", "name": "onion, diced"}, {"q": 2, "unit": "", "name": "garlic cloves, crushed"}, {"q": 15, "unit": "g", "name": "fresh ginger, grated"}, {"q": 1, "unit": "tsp", "name": "ground cumin"}, {"q": 0.5, "unit": "tsp", "name": "turmeric"}, {"q": 400, "unit": "g", "name": "tinned chopped tomatoes"}, {"q": 600, "unit": "ml", "name": "water"}, {"q": 0.5, "unit": "", "name": "lemon, juice"}, {"q": 0.5, "unit": "tsp", "name": "salt, adjust to taste"}], "steps": [{"title": "Cook the aromatics", "time": 7, "text": "Soften onion in oil over medium heat for 6–8 minutes. Add garlic and ginger and cook for 1 minute."}, {"title": "Add spices", "time": 1, "text": "Stir in cumin and turmeric for 30 seconds, then add tomatoes."}, {"title": "Cook the lentils", "time": 25, "text": "Add rinsed lentils and water. Bring to a gentle simmer and cook 20–30 minutes, stirring more frequently as it thickens. Add a splash of water if it sticks. Lentils should be completely tender with no chalky centre."}, {"title": "Balance", "time": 0, "text": "Season and add lemon juice to taste. Serve with rice or flatbreads."}], "science": "Split red lentils soften and break down, producing a naturally thick texture. Evaporation changes consistency, so water needs vary with pan width and heat.", "fix": "If still gritty, cook longer with extra water. If watery, simmer uncovered briefly.", "tags": ["Easy", "Hot", "Savoury", "Creamy"], "lesson": "starch", "foodTypes": ["Soup & Stew"]}, {"id": "mushroom-risotto", "title": "Creamy mushroom risotto", "category": "Dinner", "prep": 10, "cook": 35, "rest": 0, "serves": 2, "ingredients": [{"q": 160, "unit": "g", "name": "arborio rice"}, {"q": 250, "unit": "g", "name": "mushrooms, sliced"}, {"q": 1, "unit": "", "name": "small onion, finely diced"}, {"q": 1, "unit": "tbsp", "name": "olive oil"}, {"q": 20, "unit": "g", "name": "butter"}, {"q": 700, "unit": "ml", "name": "hot vegetable stock, use as needed"}, {"q": 30, "unit": "g", "name": "Parmesan, grated"}, {"q": 1, "unit": "pinch", "name": "black pepper"}], "steps": [{"title": "Brown mushrooms", "time": 8, "text": "Heat oil in a wide pan over medium-high heat. Cook mushrooms in a single layer for 6–8 minutes, turning once browned. Remove to a plate."}, {"title": "Soften and toast", "time": 7, "text": "Lower heat to medium-low. Melt half the butter; cook onion 5 minutes, then stir in rice for 2 minutes."}, {"title": "Add stock gradually", "time": 20, "text": "Add a ladle of hot stock and stir regularly. When nearly absorbed, add another. Continue 18–22 minutes, tasting from 16 minutes. Rice should be tender with a slight bite, without a chalky core; use more or less stock as needed."}, {"title": "Finish off heat", "time": 2, "text": "Fold in mushrooms, remaining butter and Parmesan. Add a splash of stock so it flows gently when the plate is tilted. Rest 2 minutes, then serve."}], "science": "Stirring helps release rice starch into the stock. Butter and cheese enrich the thickened liquid; cream is not needed.", "fix": "Stodgy: stir in hot stock. Hard rice: continue cooking with liquid. Do not serve rice that still has a dry, chalky centre.", "tags": ["Italian", "Moderate", "Hot", "Savoury", "Creamy"], "lesson": "rice", "foodTypes": ["Rice & Grains"]}, {"id": "egg-fried-rice", "title": "Pea & egg fried rice", "category": "Dinner", "prep": 10, "cook": 10, "rest": 0, "serves": 2, "ingredients": [{"q": 350, "unit": "g", "name": "cooked rice, safely chilled"}, {"q": 2, "unit": "", "name": "eggs, beaten"}, {"q": 100, "unit": "g", "name": "frozen peas"}, {"q": 2, "unit": "", "name": "spring onions, sliced"}, {"q": 1, "unit": "tbsp", "name": "rapeseed oil"}, {"q": 1, "unit": "tbsp", "name": "soy sauce, check label"}, {"q": 1, "unit": "", "name": "garlic clove, minced"}], "steps": [{"title": "Check the rice", "time": 0, "text": "Use rice cooled promptly, ideally within 1 hour, refrigerated and used within 24 hours. Do not use rice left sitting at room temperature for a long period."}, {"title": "Scramble", "time": 2, "text": "Heat half the oil in a large frying pan over medium-high heat. Add eggs and stir until fully set, about 1–2 minutes. Transfer to a clean plate."}, {"title": "Fry", "time": 5, "text": "Add remaining oil, garlic and spring onions. Stir for 30 seconds, add peas and cook 2 minutes. Add rice, breaking up clumps, and stir-fry 3–5 minutes until steaming hot throughout."}, {"title": "Combine", "time": 1, "text": "Return egg to the pan, add soy sauce and toss for 1 minute. Serve immediately. Reheat rice only once."}], "science": "Cooling firms cooked rice and dries the surface, helping separate grains. Safe cooling and storage matter because cooking may not destroy all bacterial spores.", "fix": "Clumping: break up chilled rice before it enters the pan. Steaming instead of frying: cook smaller batches.", "tags": ["Easy", "Hot", "Savoury"], "lesson": "rice", "safety": "rice", "foodTypes": ["Rice & Grains"]}, {"id": "quinoa-bowl", "title": "Lemon quinoa & roast vegetable bowl", "category": "Lunch", "prep": 15, "cook": 30, "rest": 5, "serves": 3, "ingredients": [{"q": 150, "unit": "g", "name": "quinoa, rinsed"}, {"q": 300, "unit": "ml", "name": "water"}, {"q": 1, "unit": "", "name": "courgette, cut into chunks"}, {"q": 2, "unit": "", "name": "carrots, cut into small chunks"}, {"q": 1, "unit": "", "name": "red pepper, cut into chunks"}, {"q": 2, "unit": "tbsp", "name": "olive oil"}, {"q": 1, "unit": "", "name": "lemon, juice"}, {"q": 100, "unit": "g", "name": "feta, optional"}, {"q": 1, "unit": "tbsp", "name": "chopped parsley"}], "steps": [{"title": "Roast vegetables", "time": 30, "text": "Heat oven to 190°C fan / 210°C conventional. Toss vegetables with half the oil and a little salt. Roast spread out on a tray for 25–30 minutes, turning halfway, until tender and golden."}, {"title": "Cook quinoa", "time": 15, "text": "Put rinsed quinoa and water in a small saucepan. Bring to a boil, cover and reduce to low. Simmer 12–15 minutes until water is absorbed and the grains show little curled tails; check the packet for variety differences."}, {"title": "Rest", "time": 5, "text": "Take quinoa off heat and leave covered for 5 minutes. Fluff with a fork."}, {"title": "Assemble", "time": 2, "text": "Toss quinoa, vegetables, remaining oil, lemon juice and parsley. Crumble over feta if using."}], "science": "Rinsing reduces surface bitterness from saponins. Covered resting redistributes moisture and makes the cooked grains easier to fluff.", "fix": "Wet quinoa: uncover and cook gently for a minute or two. Bland bowl: taste the dressing and add salt or lemon gradually.", "tags": ["Easy", "Warm", "Fresh"], "lesson": "rice", "foodTypes": ["Rice & Grains", "Vegetables"]}, {"id": "mac-cheese", "title": "Proper stovetop macaroni cheese", "category": "Dinner", "prep": 10, "cook": 20, "rest": 0, "serves": 3, "ingredients": [{"q": 240, "unit": "g", "name": "macaroni"}, {"q": 30, "unit": "g", "name": "butter"}, {"q": 30, "unit": "g", "name": "plain flour"}, {"q": 450, "unit": "ml", "name": "milk"}, {"q": 150, "unit": "g", "name": "mature Cheddar, grated"}, {"q": 0.5, "unit": "tsp", "name": "Dijon mustard, optional"}, {"q": 1, "unit": "pinch", "name": "black pepper"}], "steps": [{"title": "Boil the pasta", "time": 10, "text": "Cook macaroni in boiling salted water following the packet. Drain when just tender, reserving a mug of cooking water."}, {"title": "Make pale roux", "time": 3, "text": "Melt butter in a saucepan over medium-low heat. Add flour and stir continuously for 2–3 minutes, keeping it pale."}, {"title": "Add milk and thicken", "time": 8, "text": "Take off heat and whisk in milk a little at a time, smoothing each addition. Return to medium-low heat and stir until simmering. Cook gently 5–7 minutes until smooth and thick enough to coat a spoon."}, {"title": "Add cheese off heat", "time": 2, "text": "Remove from heat. Stir in cheese in handfuls, then mustard and pepper. Mix in pasta. Loosen with a splash of reserved water if necessary; do not boil after adding the cheese."}], "science": "The roux disperses flour in fat; milk supplies the water that lets starch swell and thicken. Gentle cheese melting reduces the chance of protein clumping.", "fix": "Grainy sauce: too much heat after adding cheese. Stop heating and stir in a small splash of milk; severe splitting may not fully recover.", "tags": ["Easy", "Hot", "Savoury", "Creamy"], "lesson": "roux", "foodTypes": ["Pasta & Noodles"]}, {"id": "tomato-soup", "title": "Roasted tomato & pepper soup", "category": "Lunch", "prep": 15, "cook": 40, "rest": 0, "serves": 4, "ingredients": [{"q": 800, "unit": "g", "name": "tomatoes, quartered"}, {"q": 2, "unit": "", "name": "red peppers, deseeded and chopped"}, {"q": 1, "unit": "", "name": "onion, quartered"}, {"q": 3, "unit": "", "name": "garlic cloves, peeled"}, {"q": 2, "unit": "tbsp", "name": "olive oil"}, {"q": 500, "unit": "ml", "name": "vegetable stock"}, {"q": 1, "unit": "tsp", "name": "dried oregano"}], "steps": [{"title": "Roast", "time": 30, "text": "Heat oven to 190°C fan / 210°C conventional. Toss tomatoes, peppers, onion and garlic with oil and oregano in a roasting tin. Roast 30–35 minutes until soft and lightly browned at the edges."}, {"title": "Simmer", "time": 10, "text": "Transfer vegetables and juices to a saucepan. Add stock and simmer for 10 minutes."}, {"title": "Blend carefully", "time": 3, "text": "Take off heat and blend with a stick blender until smooth, keeping the head submerged. If using a jug blender, cool first and follow its hot-liquid instructions; never seal steaming liquid in a non-vented blender."}, {"title": "Season", "time": 0, "text": "Taste and season. Add a little water for a lighter soup, or simmer uncovered to thicken."}], "science": "Roasting evaporates water and develops browning on exposed edges. Blending distributes vegetable solids throughout the liquid for body.", "fix": "Too acidic: a little cream or olive oil can round it out. Too thin: reduce gently, stirring so the bottom does not catch.", "tags": ["Easy", "Hot", "Savoury"], "lesson": "reduction", "foodTypes": ["Soup & Stew", "Vegetables"]}, {"id": "roast-carrots", "title": "Honey & thyme roast carrots", "category": "Dinner", "prep": 10, "cook": 35, "rest": 0, "serves": 4, "ingredients": [{"q": 700, "unit": "g", "name": "carrots, cut into even batons"}, {"q": 1.5, "unit": "tbsp", "name": "olive oil"}, {"q": 1, "unit": "tbsp", "name": "honey"}, {"q": 1, "unit": "tsp", "name": "thyme leaves"}, {"q": 1, "unit": "pinch", "name": "salt and pepper"}], "steps": [{"title": "Prepare", "time": 5, "text": "Heat oven to 190°C fan / 210°C conventional. Toss carrots with oil, thyme, salt and pepper."}, {"title": "Start roasting", "time": 20, "text": "Spread on a metal tray and roast for 20 minutes, turning once."}, {"title": "Glaze", "time": 15, "text": "Drizzle over honey, toss carefully and roast another 10–15 minutes. Stop when edges are browned and a knife slides into the thickest pieces."}], "science": "Adding honey later gives the carrots time to soften before the concentrated sugars risk burning.", "fix": "Burning edges with hard centres: cut thinner next time, lower the oven slightly and delay the honey.", "tags": ["Easy", "Hot", "Sweet"], "lesson": "browning", "foodTypes": ["Vegetables"]}, {"id": "flatbreads", "title": "Soft yoghurt pan flatbreads", "category": "Baking", "prep": 15, "cook": 15, "rest": 10, "serves": 4, "ingredients": [{"q": 250, "unit": "g", "name": "self-raising flour, plus a little for dusting"}, {"q": 200, "unit": "g", "name": "plain thick yoghurt"}, {"q": 0.5, "unit": "tsp", "name": "salt"}, {"q": 1, "unit": "tbsp", "name": "olive oil, for brushing"}], "steps": [{"title": "Make dough", "time": 5, "text": "Mix flour, salt and yoghurt to form a soft dough. Knead gently for 1–2 minutes just until together. If very sticky, dust with a little flour; if dry, add yoghurt a teaspoon at a time."}, {"title": "Rest", "time": 10, "text": "Cover and rest 10 minutes. Divide into 4 pieces."}, {"title": "Roll", "time": 5, "text": "Roll on a lightly floured surface to about 3–4 mm thick."}, {"title": "Cook", "time": 4, "text": "Heat a heavy frying pan over medium-high heat. Cook each bread about 2 minutes per side until puffed with brown spots and no raw dough inside. Lower the heat if spots burn before the middle cooks."}, {"title": "Keep soft", "time": 0, "text": "Brush lightly with oil and wrap in a clean tea towel while cooking the others."}], "science": "Self-raising flour supplies baking powder. Gas and steam puff the dough; resting makes it easier to roll without springing back.", "fix": "Tough bread: too much added flour or overworking. Burnt outside/raw inside: roll thinner and lower the heat.", "tags": ["Easy", "Warm", "Fluffy"], "lesson": "leavening", "foodTypes": []}, {"id": "apple-crumble", "title": "Apple crumble with a crisp topping", "category": "Dessert", "prep": 20, "cook": 40, "rest": 10, "serves": 6, "ingredients": [{"q": 750, "unit": "g", "name": "apples, peeled, cored and sliced"}, {"q": 40, "unit": "g", "name": "sugar, for the fruit"}, {"q": 1, "unit": "tsp", "name": "ground cinnamon"}, {"q": 1, "unit": "tbsp", "name": "water"}, {"q": 150, "unit": "g", "name": "plain flour"}, {"q": 90, "unit": "g", "name": "cold butter, diced"}, {"q": 70, "unit": "g", "name": "demerara sugar, for the topping"}], "steps": [{"title": "Prepare the fruit", "time": 10, "text": "Heat oven to 170°C fan / 190°C conventional. Put apples in a roughly 20 cm baking dish. Toss with fruit sugar, cinnamon and water."}, {"title": "Make crumbs", "time": 7, "text": "Rub cold butter into flour with fingertips until a mixture of crumbs and small clumps forms. Stir in demerara sugar; do not work it into a paste."}, {"title": "Bake", "time": 40, "text": "Scatter loosely over the apples without pressing down. Bake 35–45 minutes until golden on top and fruit juices bubble at the edges. Pierce the fruit through a gap to check it is tender."}, {"title": "Rest", "time": 10, "text": "Rest 10 minutes before serving with custard. The fruit underneath is very hot."}], "science": "Cold fat limits gluten development. Loose crumbs expose more surface to oven heat, while resting lets bubbling fruit juices thicken slightly.", "fix": "Soggy topping: avoid compacting it and use a shallow enough dish. Hard apples: cover loosely and bake longer.", "tags": ["British", "Easy", "Warm", "Sweet", "Crispy"], "lesson": "gluten", "foodTypes": []}, {"id": "custard", "title": "Vanilla pouring custard", "category": "Dessert", "prep": 10, "cook": 12, "rest": 0, "serves": 4, "ingredients": [{"q": 300, "unit": "ml", "name": "whole milk"}, {"q": 100, "unit": "ml", "name": "double cream"}, {"q": 3, "unit": "", "name": "egg yolks"}, {"q": 40, "unit": "g", "name": "caster sugar"}, {"q": 1, "unit": "tsp", "name": "vanilla extract"}], "steps": [{"title": "Prepare", "time": 5, "text": "Set a sieve over a heatproof jug. Whisk yolks and sugar just until blended. Put milk and cream in a saucepan."}, {"title": "Warm dairy", "time": 4, "text": "Heat dairy over medium-low heat until steaming with tiny bubbles around the edge. Do not let it boil."}, {"title": "Temper", "time": 2, "text": "While whisking the yolks, slowly pour in the hot dairy. Return everything to the saucepan."}, {"title": "Thicken gently", "time": 6, "text": "Stir constantly over low heat, scraping the bottom and corners, for roughly 5–8 minutes. Aim for 82–84°C and a coating on the back of a spoon; do not boil. It should pour, not set like pudding."}, {"title": "Strain", "time": 1, "text": "Immediately pour through the sieve and stir in vanilla. Serve, or cool promptly and refrigerate. It thickens further as it cools."}], "science": "Egg proteins unfold and form a loose network that thickens liquid. Excessive heat tightens that network into curds and squeezes out water.", "fix": "At the first grainy appearance, remove from heat and strain into a cool jug. Fully scrambled custard cannot be restored to the same silky structure.", "tags": ["Moderate", "Warm", "Sweet", "Silky"], "lesson": "proteins", "foodTypes": [], "equipment": "Saucepan, whisk, silicone spatula, thermometer, sieve and heatproof jug."}, {"id": "caramel-sauce", "title": "Amber salted caramel sauce", "category": "Dessert", "prep": 10, "cook": 15, "rest": 30, "serves": 8, "ingredients": [{"q": 150, "unit": "g", "name": "white caster sugar"}, {"q": 45, "unit": "ml", "name": "water"}, {"q": 120, "unit": "ml", "name": "double cream"}, {"q": 30, "unit": "g", "name": "butter, diced"}, {"q": 0.25, "unit": "tsp", "name": "fine salt, adjust after cooling"}], "steps": [{"title": "Set up first", "time": 5, "text": "Use a clean, light-coloured, deep saucepan of at least 1.5 litres and a long-handled whisk. Warm the cream gently in another pan, then take it off heat. Keep children away: molten sugar causes serious burns."}, {"title": "Dissolve", "time": 4, "text": "Put sugar and water in the caramel pan. Heat gently, stirring only until dissolved. Once boiling, stop stirring; gently swirl if colour develops unevenly."}, {"title": "Watch the colour", "time": 8, "text": "Boil over medium heat for approximately 5–10 minutes. It will go from clear to straw, then honey-coloured and amber. Watch continuously as it colours. Remove at amber, before dark smoke or an acrid smell."}, {"title": "Add cream carefully", "time": 2, "text": "Off heat, gradually add the warm cream in several small additions. It will bubble vigorously and release steam; keep face and hands back. Whisk carefully, then add butter. If hard lumps remain, warm gently until dissolved."}, {"title": "Cool before tasting", "time": 30, "text": "Allow to cool for at least 30 minutes and verify it is safe to taste. Add salt to taste. The sauce will thicken as it cools; never taste hot caramel from the pan."}], "science": "Heating sugar develops new colour and flavour compounds. Undissolved crystals can seed further crystallisation; avoiding agitation after boiling helps keep the syrup smooth.", "fix": "Black or acrid caramel: cool safely and remake; bitterness cannot be removed. Hardened pieces after cream: gentle reheating can dissolve them.", "tags": ["Moderate", "Sweet", "Saucy"], "lesson": "caramel", "foodTypes": [], "equipment": "Deep light-coloured saucepan (at least 1.5 litres), second pan, long-handled whisk and heatproof jug."}, {"id": "choc-cookies", "title": "Chocolate chunk cookies", "category": "Baking", "prep": 15, "cook": 12, "rest": 30, "serves": 12, "ingredients": [{"q": 110, "unit": "g", "name": "soft butter"}, {"q": 90, "unit": "g", "name": "light brown sugar"}, {"q": 50, "unit": "g", "name": "caster sugar"}, {"q": 1, "unit": "", "name": "medium egg"}, {"q": 1, "unit": "tsp", "name": "vanilla extract"}, {"q": 180, "unit": "g", "name": "plain flour"}, {"q": 0.5, "unit": "tsp", "name": "bicarbonate of soda"}, {"q": 0.25, "unit": "tsp", "name": "salt"}, {"q": 120, "unit": "g", "name": "chocolate chunks, check allergy label"}], "steps": [{"title": "Mix the base", "time": 4, "text": "Beat butter and sugars until evenly creamy, about 2 minutes. Beat in egg and vanilla until combined."}, {"title": "Add dry ingredients", "time": 3, "text": "Mix flour, bicarbonate and salt separately, then stir into the butter mixture just until no dry flour remains. Fold in chocolate."}, {"title": "Chill", "time": 30, "text": "Cover and chill 30 minutes. Heat oven to 160°C fan / 180°C conventional and line two trays."}, {"title": "Portion and bake", "time": 12, "text": "Divide into 12 balls and space well apart. Bake 10–13 minutes until edges are set and lightly golden but centres still look soft. Rotate trays if your oven browns unevenly."}, {"title": "Set on tray", "time": 10, "text": "Leave on the tray 10 minutes, then transfer to a rack. They firm as they cool; do not judge texture while hot."}], "science": "Cold dough spreads more slowly while the flour hydrates. Sugar attracts moisture; baking longer shifts the result from soft-centred towards crisp.", "fix": "Excess spread: dough too warm or butter too soft. Dry cookies: too much flour or too long in the oven.", "tags": ["Easy", "Sweet", "Chewy"], "lesson": "gluten", "foodTypes": []}, {"id": "brownies", "title": "Fudgy chocolate brownies", "category": "Baking", "prep": 20, "cook": 25, "rest": 60, "serves": 9, "ingredients": [{"q": 120, "unit": "g", "name": "butter"}, {"q": 160, "unit": "g", "name": "dark chocolate, check allergy label"}, {"q": 180, "unit": "g", "name": "caster sugar"}, {"q": 2, "unit": "", "name": "medium eggs"}, {"q": 70, "unit": "g", "name": "plain flour"}, {"q": 20, "unit": "g", "name": "cocoa powder"}, {"q": 0.25, "unit": "tsp", "name": "salt"}], "steps": [{"title": "Prepare", "time": 5, "text": "Heat oven to 160°C fan / 180°C conventional. Line a 20 cm square metal tin."}, {"title": "Melt", "time": 5, "text": "Gently melt butter and chocolate in a heatproof bowl over barely simmering water, keeping the bowl above the water. Stir smooth and allow to cool until warm."}, {"title": "Mix", "time": 5, "text": "Whisk eggs and sugar for 1–2 minutes. Stir in chocolate mixture. Sift in flour, cocoa and salt; fold only until combined."}, {"title": "Bake", "time": 25, "text": "Spread in the tin. Bake 22–28 minutes. The edges should be set and a skewer near the centre should have moist crumbs, not liquid batter. Avoid baking until it comes out completely dry."}, {"title": "Cool", "time": 60, "text": "Cool fully in the tin, at least 1 hour, before cutting into 9 squares."}], "science": "A relatively low flour content limits a cake-like structure. Cooling lets melted chocolate and butter firm, so the hot centre is not the final texture.", "fix": "Raw liquid centre: return to oven for a few minutes. Dry texture: reduce baking time next time and measure flour carefully.", "tags": ["Moderate", "Sweet", "Rich"], "lesson": "proteins", "foodTypes": [], "equipment": "20 cm square metal tin, baking paper, bowl, saucepan and spatula."}, {"id": "vanilla-cupcakes", "title": "Vanilla cupcakes", "category": "Baking", "prep": 20, "cook": 20, "rest": 30, "serves": 12, "ingredients": [{"q": 125, "unit": "g", "name": "soft butter"}, {"q": 125, "unit": "g", "name": "caster sugar"}, {"q": 2, "unit": "", "name": "medium eggs, room temperature"}, {"q": 125, "unit": "g", "name": "self-raising flour"}, {"q": 2, "unit": "tbsp", "name": "milk"}, {"q": 1, "unit": "tsp", "name": "vanilla extract"}], "steps": [{"title": "Prepare", "time": 5, "text": "Heat oven to 160°C fan / 180°C conventional. Line a 12-hole muffin tin with paper cases."}, {"title": "Cream", "time": 4, "text": "Beat butter and sugar for 3–4 minutes until paler and fluffy. Scrape down the bowl."}, {"title": "Combine gently", "time": 5, "text": "Beat in eggs a little at a time. Fold in flour, milk and vanilla just until smooth; avoid prolonged beating once flour is added."}, {"title": "Bake", "time": 20, "text": "Divide evenly between cases. Bake 18–22 minutes until tops spring back lightly and a skewer comes out without wet batter."}, {"title": "Cool", "time": 30, "text": "Rest in tin 5 minutes, then move to a rack. Cool completely before adding icing."}], "science": "Creaming traps air; baking powder produces gas that expands in the oven. Flour and egg proteins set around those bubbles.", "fix": "Dense cakes: butter too cold, insufficient creaming or overmixing after flour. Sunken centres: underbaking or opening the oven too early.", "tags": ["Easy", "Sweet", "Fluffy"], "lesson": "leavening", "foodTypes": [], "equipment": "12-hole muffin tin, paper cases, scales, bowl, electric whisk or wooden spoon and cooling rack."}, {"id": "berry-compote", "title": "Quick berry compote", "category": "Dessert", "prep": 5, "cook": 10, "rest": 10, "serves": 4, "ingredients": [{"q": 300, "unit": "g", "name": "fresh or frozen mixed berries"}, {"q": 30, "unit": "g", "name": "sugar"}, {"q": 1, "unit": "tbsp", "name": "lemon juice"}, {"q": 1, "unit": "tbsp", "name": "water"}], "steps": [{"title": "Combine", "time": 2, "text": "Put berries, sugar, lemon and water in a small saucepan."}, {"title": "Simmer", "time": 10, "text": "Bring to a gentle simmer over medium heat, then lower heat and cook 8–12 minutes, stirring occasionally, until fruit softens and juice lightly coats a spoon."}, {"title": "Cool a little", "time": 10, "text": "Rest 10 minutes. Taste when safe and adjust sweetness or acidity. Serve over pancakes or yoghurt."}], "science": "Heat breaks down fruit structure and evaporates water. The sauce thickens further on cooling; reduction controls the final concentration.", "fix": "Too thick: add a splash of water. Too thin: simmer uncovered for a few more minutes.", "tags": ["Very easy", "Sweet", "Tangy", "Saucy"], "lesson": "reduction", "foodTypes": []}, {"id": "hibiscus", "title": "Spiced hibiscus & citrus drink", "category": "Drinks", "prep": 10, "cook": 10, "rest": 10, "serves": 4, "ingredients": [{"q": 15, "unit": "g", "name": "food-grade dried hibiscus"}, {"q": 1000, "unit": "ml", "name": "water"}, {"q": 1, "unit": "", "name": "cinnamon stick"}, {"q": 3, "unit": "", "name": "whole cloves"}, {"q": 0.5, "unit": "", "name": "orange, sliced"}, {"q": 0.5, "unit": "", "name": "lemon, juice"}, {"q": 0.5, "unit": "", "name": "lime, juice"}, {"q": 2, "unit": "tbsp", "name": "honey, adjust to taste"}], "steps": [{"title": "Infuse the spices", "time": 10, "text": "Bring water, cinnamon and cloves to a gentle simmer. Cover and simmer 8–10 minutes."}, {"title": "Steep hibiscus", "time": 10, "text": "Remove from heat. Add hibiscus and orange; cover and steep for 8–10 minutes."}, {"title": "Strain and balance", "time": 2, "text": "Strain through a fine sieve. Stir in lemon, lime and honey. Taste cautiously once cooler, adding water if too tart."}, {"title": "Serve", "time": 0, "text": "Serve warm, or cool promptly and refrigerate for an iced drink. Start with less honey if you prefer it sharp."}], "science": "Hot water extracts acids, pigments and aromatic compounds. Longer steeping strengthens flavour, but can also increase astringency.", "fix": "Too tart: dilute first, then sweeten gradually. Gritty: strain through a finer sieve or clean cloth.", "tags": ["Easy", "Warm", "Tangy"], "lesson": "extraction", "foodTypes": [], "equipment": "Lidded saucepan, fine sieve, measuring jug and mugs."}, {"id": "berry-smoothie", "title": "Banana-free berry & oat smoothie", "category": "Drinks", "prep": 5, "cook": 0, "rest": 0, "serves": 2, "ingredients": [{"q": 200, "unit": "g", "name": "berries, ready to eat; follow packet cooking advice for frozen fruit"}, {"q": 150, "unit": "g", "name": "plain yoghurt"}, {"q": 200, "unit": "ml", "name": "milk or suitable oat drink"}, {"q": 30, "unit": "g", "name": "porridge oats"}, {"q": 1, "unit": "tsp", "name": "honey, optional"}], "steps": [{"title": "Load", "time": 2, "text": "Put liquid and yoghurt into a blender, then add oats and berries. If a frozen-fruit packet requires cooking, cook as directed and cool before using."}, {"title": "Blend", "time": 1, "text": "Blend 45–60 seconds until smooth. Pause and scrape if needed, with the machine switched off."}, {"title": "Adjust", "time": 1, "text": "Add more liquid a tablespoon at a time for a thinner drink. Taste before adding honey and serve promptly."}], "science": "Yoghurt contributes body and oats bind water, providing thickness without banana. Small particles stay suspended more easily after thorough blending.", "fix": "Too thick: add liquid. Gritty: blend longer or soak oats in the milk for 10 minutes first.", "tags": ["Very easy", "Chilled", "Sweet", "Creamy"], "lesson": "extraction", "foodTypes": [], "equipment": "Blender, measuring jug and glasses."}, {"id": "bechamel", "title": "Smooth béchamel white sauce", "category": "Sauces", "prep": 5, "cook": 12, "rest": 0, "serves": 4, "ingredients": [{"q": 40, "unit": "g", "name": "butter"}, {"q": 40, "unit": "g", "name": "plain flour"}, {"q": 500, "unit": "ml", "name": "milk"}, {"q": 0.25, "unit": "tsp", "name": "salt"}, {"q": 1, "unit": "pinch", "name": "black pepper or nutmeg, optional"}], "steps": [{"title": "Melt butter", "time": 2, "text": "Use a medium heavy saucepan over medium-low heat. Melt butter gently without browning."}, {"title": "Cook the roux", "time": 3, "text": "Stir in flour and cook 2–3 minutes, stirring the base and corners continuously. It should bubble gently and stay pale."}, {"title": "Whisk in milk", "time": 3, "text": "Take off heat. Add milk in small additions, whisking smooth each time. Start with a few tablespoons, then add more as it loosens."}, {"title": "Simmer", "time": 7, "text": "Return to medium-low heat. Stir until gently simmering, then cook 5–7 minutes, scraping the corners, until smooth and coating a spoon. Season after thickening."}], "science": "Fat separates the flour particles. When milk is added and heated, starch absorbs water and swells, building the sauce texture.", "fix": "Lumps: take off heat and whisk firmly or strain. Too thick: add milk gradually. Burnt bottom: move unburnt sauce to a clean pan without scraping.", "tags": ["Easy", "Hot", "Savoury", "Silky"], "lesson": "roux", "foodTypes": []}, {"id": "pan-gravy", "title": "Simple onion gravy", "category": "Sauces", "prep": 10, "cook": 25, "rest": 0, "serves": 4, "ingredients": [{"q": 1, "unit": "", "name": "large onion, thinly sliced"}, {"q": 25, "unit": "g", "name": "butter"}, {"q": 20, "unit": "g", "name": "plain flour"}, {"q": 500, "unit": "ml", "name": "stock, low salt if possible"}, {"q": 1, "unit": "tsp", "name": "Worcestershire sauce, optional; check allergens"}], "steps": [{"title": "Soften and colour", "time": 15, "text": "Melt butter over medium-low heat. Cook onion for 12–15 minutes, stirring regularly, until soft and golden. This is lightly browned onion, not deeply caramelised onion."}, {"title": "Cook flour", "time": 2, "text": "Stir in flour and cook 2 minutes, scraping the pan constantly."}, {"title": "Whisk and simmer", "time": 8, "text": "Add stock gradually, stirring smooth between additions. Bring to a gentle simmer and cook 7–10 minutes until the flour taste is gone and gravy coats a spoon."}, {"title": "Season", "time": 0, "text": "Add Worcestershire sauce if using. Taste before adding salt because stock may already contain plenty."}], "science": "Onion browning adds savoury depth; flour thickens the stock as its starch hydrates during simmering.", "fix": "Too salty: dilute with unsalted stock and re-thicken if needed. Too pale: take longer over the onions next time.", "tags": ["Easy", "Hot", "Savoury", "Saucy"], "lesson": "roux", "foodTypes": []}, {"id": "brown-butter", "title": "Brown butter for pasta or baking", "category": "Sauces", "prep": 5, "cook": 8, "rest": 5, "serves": 6, "ingredients": [{"q": 100, "unit": "g", "name": "unsalted butter"}], "steps": [{"title": "Prepare", "time": 1, "text": "Set a heatproof bowl beside the hob. Use a light-coloured saucepan so you can see the milk solids."}, {"title": "Melt and foam", "time": 4, "text": "Melt butter over medium-low heat, stirring or swirling. It will bubble and foam as water evaporates."}, {"title": "Watch the solids", "time": 4, "text": "Continue 3–5 minutes, stirring and checking beneath the foam. Stop when the specks turn golden-brown and the aroma becomes toasted; timing varies with pan and heat."}, {"title": "Stop the cooking", "time": 1, "text": "Immediately pour into the heatproof bowl, including brown specks. Let cool to the temperature needed for your recipe. Do not leave it in the hot pan."}], "science": "Butter contains water, fat and milk solids. After much of the water evaporates, the milk solids brown and develop toasted flavours. Some weight is lost as steam.", "fix": "Black specks and an acrid smell mean it has burnt; remake. Do not substitute it by weight in baking without allowing for lost water.", "tags": ["Moderate", "Savoury", "Rich"], "lesson": "brown-butter", "foodTypes": [], "equipment": "Light-coloured saucepan, spatula and heatproof bowl."}, {"id": "pizza-practice", "title": "Practice kitchen: simple cheese pizza", "category": "Dinner", "prep": 25, "cook": 15, "rest": 75, "serves": 2, "ingredients": [{"q": 250, "unit": "g", "name": "strong white bread flour"}, {"q": 160, "unit": "ml", "name": "lukewarm water"}, {"q": 3, "unit": "g", "name": "instant yeast"}, {"q": 5, "unit": "g", "name": "salt"}, {"q": 1, "unit": "tbsp", "name": "olive oil"}, {"q": 100, "unit": "g", "name": "passata"}, {"q": 0.5, "unit": "tsp", "name": "dried oregano"}, {"q": 125, "unit": "g", "name": "mozzarella, drained and torn"}], "steps": [{"title": "Mix and knead", "time": 12, "text": "Combine flour, yeast and salt. Add water and oil; mix, then knead 8–10 minutes until smoother and elastic. Water should feel lukewarm, not hot."}, {"title": "First rise", "time": 60, "text": "Cover in a lightly oiled bowl and leave in a warm room for about 60–90 minutes, until noticeably puffy and roughly doubled. The dough, not the clock, determines readiness."}, {"title": "Heat and shape", "time": 15, "text": "Heat oven to 230°C fan / 250°C conventional with a sturdy baking tray inside. On floured baking paper suitable for your oven temperature, stretch dough into a roughly 30 cm base; otherwise use an oiled pizza tray. Rest 10 minutes if it keeps springing back."}, {"title": "Top and bake", "time": 15, "text": "Spread with passata mixed with oregano and a pinch of salt, then add mozzarella. Transfer carefully to the hot tray or use the pizza tray. Bake 10–15 minutes until the base is cooked underneath, edges browned and cheese bubbling."}, {"title": "Rest briefly", "time": 2, "text": "Rest 2 minutes before slicing. This is a separate practice recipe; Naomi’s recorded pepperoni pizza ingredients remain unchanged."}], "science": "Kneading develops a gluten network that holds yeast gas. Strong bottom heat helps the base cook before wet toppings soak into it.", "fix": "Soggy middle: drain cheese, use less sauce and preheat thoroughly. Tight dough: rest it before stretching.", "tags": ["Italian", "Moderate", "Hot", "Savoury", "Crispy"], "lesson": "gluten", "foodTypes": ["Pizza"]}, {"id": "ginger-lemon-tea", "title": "Fresh ginger, lemon & honey tea", "category": "Drinks", "prep": 5, "cook": 10, "rest": 3, "serves": 2, "ingredients": [{"q": 20, "unit": "g", "name": "fresh ginger, washed and thinly sliced"}, {"q": 600, "unit": "ml", "name": "water"}, {"q": 2, "unit": "tbsp", "name": "lemon juice"}, {"q": 2, "unit": "tsp", "name": "honey"}], "steps": [{"title": "Prepare the ginger", "time": 5, "text": "Scrub the ginger and cut into thin slices. Put it in a small saucepan with the water."}, {"title": "Extract the flavour", "time": 10, "text": "Bring to a boil, then lower to a gentle simmer for 8–10 minutes. Cover loosely; the water should bubble gently."}, {"title": "Strain and finish", "time": 3, "text": "Strain into a heatproof jug. Stir in lemon and honey. Divide between two mugs and let cool to a comfortable drinking temperature."}], "science": "Thin slices expose more surface area, helping ginger flavour move into the water. Adding lemon at the end preserves its fresh aroma.", "fix": "Too fiery: dilute with hot water. Too sharp: use less lemon next time; add honey in small amounts.", "lesson": "extraction", "equipment": "Measuring jug, small saucepan, sieve and two heatproof mugs.", "tags": ["Easy", "Sweet", "Warm"], "foodTypes": []}, {"id": "spiced-milk-tea", "title": "Cinnamon, cardamom & ginger milk tea", "category": "Drinks", "prep": 5, "cook": 10, "rest": 2, "serves": 2, "ingredients": [{"q": 300, "unit": "ml", "name": "water"}, {"q": 250, "unit": "ml", "name": "milk"}, {"q": 2, "unit": "", "name": "black tea bags"}, {"q": 1, "unit": "", "name": "cinnamon stick"}, {"q": 3, "unit": "", "name": "cardamom pods, lightly crushed"}, {"q": 10, "unit": "g", "name": "fresh ginger, sliced"}, {"q": 2, "unit": "tsp", "name": "sugar"}], "steps": [{"title": "Simmer the spices", "time": 6, "text": "Put water, cinnamon, cardamom and ginger in a saucepan. Bring to a simmer and cook gently for 6 minutes."}, {"title": "Brew the tea", "time": 3, "text": "Take off the heat, add tea bags and steep for 3 minutes. Remove the bags without squeezing."}, {"title": "Add the milk", "time": 4, "text": "Stir in milk and sugar. Warm over low heat for 2–4 minutes, stirring, until steaming. Do not let it boil over. Strain and divide into mugs."}], "science": "Spices extract into hot water before milk is added. Keeping the tea steep short limits bitterness from prolonged extraction.", "fix": "Bitter: steep the tea for less time. Weak spice flavour: simmer the spices longer before adding tea.", "lesson": "extraction", "equipment": "Measuring jug, small saucepan, sieve and two heatproof mugs.", "tags": ["Easy", "Sweet", "Warm"], "foodTypes": []}, {"id": "real-hot-chocolate", "title": "Silky real-chocolate hot chocolate", "category": "Drinks", "prep": 5, "cook": 6, "rest": 2, "serves": 2, "ingredients": [{"q": 500, "unit": "ml", "name": "milk"}, {"q": 60, "unit": "g", "name": "dark chocolate, finely chopped; check allergy label"}, {"q": 2, "unit": "tsp", "name": "cocoa powder"}, {"q": 1, "unit": "tsp", "name": "sugar, optional"}, {"q": 1, "unit": "pinch", "name": "salt"}], "steps": [{"title": "Make a cocoa paste", "time": 2, "text": "Whisk cocoa and sugar with 2 tablespoons of the measured milk in a saucepan until smooth."}, {"title": "Warm gently", "time": 4, "text": "Whisk in the remaining milk and salt. Heat over medium-low heat for 3–4 minutes, stirring, until steaming with tiny bubbles at the edge."}, {"title": "Melt and emulsify", "time": 2, "text": "Take off the heat. Add chopped chocolate and whisk for 1–2 minutes until smooth. Divide into mugs; allow to cool before sipping."}], "science": "Making a paste disperses dry cocoa before adding all the liquid. Gentle heat melts chocolate; whisking distributes its fat through the milk.", "fix": "Grainy: take off the heat and whisk in a splash of warm milk. Scorched milk cannot be fixed; start again on lower heat.", "lesson": "emulsions", "equipment": "Measuring jug, small saucepan, sieve and two heatproof mugs.", "tags": ["Easy", "Sweet", "Warm"], "foodTypes": []}, {"id": "vanilla-london-fog", "title": "Vanilla Earl Grey milk tea", "category": "Drinks", "prep": 3, "cook": 4, "rest": 3, "serves": 2, "ingredients": [{"q": 250, "unit": "ml", "name": "water"}, {"q": 250, "unit": "ml", "name": "milk"}, {"q": 2, "unit": "", "name": "Earl Grey tea bags"}, {"q": 0.5, "unit": "tsp", "name": "vanilla extract"}, {"q": 2, "unit": "tsp", "name": "honey"}], "steps": [{"title": "Brew", "time": 3, "text": "Bring water to a boil. Pour over tea bags in a heatproof jug and steep for 3 minutes, then remove."}, {"title": "Warm the milk", "time": 4, "text": "Heat milk gently in a small saucepan for 3–4 minutes until steaming, without boiling."}, {"title": "Combine", "time": 2, "text": "Stir vanilla and honey into the tea. Divide into mugs, top with milk and whisk briefly for a little foam."}], "science": "Tea strength depends on both steeping time and dilution. A concentrated brew keeps its flavour after the milk is added.", "fix": "Bitter: shorten the steep. Too milky: replace a little milk with hot water.", "lesson": "extraction", "equipment": "Measuring jug, small saucepan, sieve and two heatproof mugs.", "tags": ["Easy", "Sweet", "Warm"], "foodTypes": []}, {"id": "strawberry-oat-smoothie", "title": "Strawberry, yoghurt & oat smoothie", "category": "Drinks", "prep": 8, "cook": 0, "rest": 0, "serves": 2, "ingredients": [{"q": 250, "unit": "g", "name": "fresh strawberries, washed and hulled"}, {"q": 200, "unit": "g", "name": "plain yoghurt"}, {"q": 200, "unit": "ml", "name": "milk"}, {"q": 30, "unit": "g", "name": "rolled oats"}, {"q": 1, "unit": "tsp", "name": "honey, optional"}], "steps": [{"title": "Prepare", "time": 3, "text": "Wash and hull the strawberries. Measure all ingredients. Check oats and dairy labels for allergy suitability."}, {"title": "Blend", "time": 2, "text": "Add milk and yoghurt to the blender first, then strawberries, oats and honey. Blend for 45–60 seconds until smooth."}, {"title": "Adjust and serve", "time": 3, "text": "Rest for 2 minutes so the oats soften, then blend briefly again. Add milk a tablespoon at a time if too thick. Pour into two glasses and serve promptly."}], "science": "Oats absorb liquid and gradually thicken the drink. Adding liquid first helps blender blades circulate the ingredients.", "fix": "Too thick: blend in more milk. Gritty: blend longer and give the oats a short soak.", "lesson": "starch", "equipment": "Blender, scales, measuring jug and two glasses.", "tags": ["Easy", "Sweet", "Chilled"], "foodTypes": []}, {"id": "mango-lassi", "title": "Mango & cardamom yoghurt lassi", "category": "Drinks", "prep": 8, "cook": 0, "rest": 0, "serves": 2, "ingredients": [{"q": 250, "unit": "g", "name": "ripe mango flesh"}, {"q": 250, "unit": "g", "name": "plain yoghurt"}, {"q": 150, "unit": "ml", "name": "cold water"}, {"q": 0.25, "unit": "tsp", "name": "ground cardamom"}, {"q": 1, "unit": "tsp", "name": "honey, optional"}], "steps": [{"title": "Prepare the fruit", "time": 4, "text": "Wash the mango before cutting. Slice the flesh away from the stone, remove the skin and weigh 250 g."}, {"title": "Blend", "time": 2, "text": "Blend mango, yoghurt, water and cardamom for 45–60 seconds until smooth."}, {"title": "Taste and pour", "time": 2, "text": "Taste before adding optional honey. Add a little more water if the drink does not pour easily. Divide into two glasses."}], "science": "Yoghurt supplies acidity and a thick protein network; water loosens it and mango pulp adds body.", "fix": "Fibrous: use a ripe mango and blend longer. Too tart: choose sweeter fruit or add a little honey.", "lesson": "proteins", "equipment": "Blender, knife, board, scales and two glasses.", "tags": ["Easy", "Sweet", "Chilled", "Indian"], "foodTypes": []}, {"id": "pineapple-lime-cooler", "title": "Pineapple & lime cooler", "category": "Drinks", "prep": 10, "cook": 0, "rest": 0, "serves": 2, "ingredients": [{"q": 250, "unit": "g", "name": "fresh pineapple flesh"}, {"q": 250, "unit": "ml", "name": "cold water"}, {"q": 1, "unit": "tbsp", "name": "lime juice"}, {"q": 150, "unit": "ml", "name": "sparkling water"}, {"q": 100, "unit": "g", "name": "ice"}], "steps": [{"title": "Prepare", "time": 5, "text": "Remove pineapple skin, eyes and the tough core; weigh the prepared flesh."}, {"title": "Blend", "time": 2, "text": "Blend pineapple, cold still water and lime juice for 45–60 seconds. Strain through a sieve if you prefer a smoother drink."}, {"title": "Add sparkle", "time": 3, "text": "Divide ice and pineapple mixture between two large glasses. Pour in sparkling water gently and stir once. Never blend sparkling water in a closed blender."}], "science": "Blending breaks fruit into suspended pulp. Sparkling water loses gas rapidly when agitated, so it goes in last.", "fix": "Too sharp: use riper pineapple or dilute with still water. Too pulpy: strain.", "lesson": "extraction", "equipment": "Blender, sieve, jug and two tall glasses.", "tags": ["Easy", "Tangy", "Chilled"], "foodTypes": []}, {"id": "watermelon-mint", "title": "Watermelon, mint & lime refresher", "category": "Drinks", "prep": 10, "cook": 0, "rest": 0, "serves": 2, "ingredients": [{"q": 500, "unit": "g", "name": "chilled watermelon flesh, seeds removed"}, {"q": 1, "unit": "tbsp", "name": "lime juice"}, {"q": 6, "unit": "", "name": "fresh mint leaves, washed"}, {"q": 100, "unit": "ml", "name": "cold water"}, {"q": 100, "unit": "g", "name": "ice"}], "steps": [{"title": "Prepare", "time": 5, "text": "Wash the melon rind before cutting. Remove rind and large seeds, then weigh the flesh."}, {"title": "Blend", "time": 2, "text": "Blend melon, lime, mint and water for 30–45 seconds until smooth. Strain if desired."}, {"title": "Serve", "time": 3, "text": "Divide ice into two glasses and pour over the juice. Stir before drinking if pulp settles."}], "science": "Fruit pulp can settle because it is denser than the surrounding liquid. This is normal separation, not a sign that the drink failed.", "fix": "Mint too strong: use fewer leaves next time. Watery melon: reduce the added water.", "lesson": "extraction", "equipment": "Blender, knife, board and two large glasses.", "tags": ["Easy", "Fresh", "Chilled"], "foodTypes": []}, {"id": "cucumber-lime-spritz", "title": "Cucumber & lime sparkling cooler", "category": "Drinks", "prep": 10, "cook": 0, "rest": 0, "serves": 2, "ingredients": [{"q": 150, "unit": "g", "name": "cucumber, washed and chopped"}, {"q": 100, "unit": "ml", "name": "cold water"}, {"q": 2, "unit": "tbsp", "name": "lime juice"}, {"q": 2, "unit": "tsp", "name": "sugar"}, {"q": 300, "unit": "ml", "name": "sparkling water"}, {"q": 100, "unit": "g", "name": "ice"}], "steps": [{"title": "Blend the base", "time": 3, "text": "Blend cucumber, still water, lime and sugar for 30 seconds."}, {"title": "Strain", "time": 4, "text": "Pour through a fine sieve into a jug. Press gently with a spoon; discard the coarse pulp."}, {"title": "Finish", "time": 3, "text": "Divide the base and ice between glasses. Add sparkling water just before serving and stir gently."}], "science": "Straining removes coarse fibre for a lighter texture. Adding bubbles at the end keeps more dissolved gas in the drink.", "fix": "Too tart: add less lime. Flat: use freshly opened sparkling water and avoid vigorous stirring.", "lesson": "extraction", "equipment": "Blender, fine sieve, jug and two tall glasses.", "tags": ["Easy", "Fresh", "Chilled"], "foodTypes": []}, {"id": "peach-iced-tea", "title": "Peach & lemon iced tea", "category": "Drinks", "prep": 10, "cook": 8, "rest": 60, "serves": 2, "ingredients": [{"q": 2, "unit": "", "name": "ripe peaches, washed, stoned and diced"}, {"q": 600, "unit": "ml", "name": "water"}, {"q": 2, "unit": "", "name": "black tea bags"}, {"q": 2, "unit": "tsp", "name": "sugar"}, {"q": 1, "unit": "tbsp", "name": "lemon juice"}, {"q": 100, "unit": "g", "name": "ice"}], "steps": [{"title": "Soften the peaches", "time": 8, "text": "Put peaches, sugar and 200 ml of the water into a saucepan. Simmer gently for 6–8 minutes until soft; mash with a fork."}, {"title": "Brew the tea", "time": 3, "text": "Boil the remaining 400 ml water. Steep tea bags in it for 3 minutes, then remove."}, {"title": "Strain and cool", "time": 60, "text": "Strain peach mixture into a heatproof jug, mix with tea and lemon. Cool the jug in cold water, then refrigerate until chilled, about 1 hour. Serve over ice."}], "science": "Cooking softens the peach tissue and releases juice. Brewing tea separately lets you control bitterness without limiting fruit extraction.", "fix": "Cloudy tea can still taste good. Bitter: reduce the tea steep rather than adding more sugar.", "lesson": "extraction", "equipment": "Saucepan, heatproof jug, sieve and two large glasses.", "tags": ["Easy", "Sweet", "Chilled"], "foodTypes": []}, {"id": "orange-carrot-smoothie", "title": "Orange, carrot & ginger smoothie", "category": "Drinks", "prep": 12, "cook": 0, "rest": 0, "serves": 2, "ingredients": [{"q": 2, "unit": "", "name": "oranges"}, {"q": 100, "unit": "g", "name": "carrot, washed and finely grated"}, {"q": 5, "unit": "g", "name": "fresh ginger, peeled and grated"}, {"q": 200, "unit": "ml", "name": "cold water"}, {"q": 100, "unit": "g", "name": "plain yoghurt"}], "steps": [{"title": "Prepare", "time": 7, "text": "Peel the oranges and remove seeds. Grate carrot and ginger finely so the blender can break them down."}, {"title": "Blend", "time": 3, "text": "Add water, yoghurt, oranges, carrot and ginger to a blender. Blend for 60–90 seconds until as smooth as your blender allows."}, {"title": "Adjust", "time": 2, "text": "Add a splash of water if too thick. Pour into two glasses. Some fine fibre is normal; use a sieve if you prefer a juice-like drink."}], "science": "Grating reduces the size of tough carrot pieces before blending. Keeping the whole orange flesh gives a thicker drink than juice alone.", "fix": "Too fibrous: grate more finely and blend longer. Too gingery: reduce ginger next time.", "lesson": "extraction", "equipment": "Blender, fine grater, board and two glasses.", "tags": ["Easy", "Fresh", "Chilled"], "foodTypes": []}, {"id": "apple-cinnamon-warmer", "title": "Apple, cinnamon & clove warmer", "category": "Drinks", "prep": 3, "cook": 12, "rest": 3, "serves": 2, "ingredients": [{"q": 500, "unit": "ml", "name": "apple juice"}, {"q": 100, "unit": "ml", "name": "water"}, {"q": 1, "unit": "", "name": "cinnamon stick"}, {"q": 2, "unit": "", "name": "whole cloves"}, {"q": 2, "unit": "", "name": "thin orange slices, washed"}], "steps": [{"title": "Combine", "time": 3, "text": "Pour juice and water into a small saucepan. Add cinnamon, cloves and orange slices."}, {"title": "Warm and infuse", "time": 12, "text": "Heat gently until steaming, then maintain very low heat for 10–12 minutes without a hard boil."}, {"title": "Strain", "time": 3, "text": "Remove spices and orange with a sieve. Divide between heatproof mugs and let cool before sipping."}], "science": "Gentle heat extracts spice aromas while limiting evaporation. A long hard boil concentrates sweetness and can make the drink cloying.", "fix": "Cloves overpower quickly: use only two for this batch. Too sweet: add hot water.", "lesson": "extraction", "equipment": "Measuring jug, small saucepan, sieve and two heatproof mugs.", "tags": ["Easy", "Sweet", "Warm"], "foodTypes": []}, {"id": "crispy-chickpeas", "title": "Smoky oven-roasted chickpeas", "category": "Lunch", "prep": 10, "cook": 35, "rest": 10, "serves": 4, "ingredients": [{"q": 480, "unit": "g", "name": "drained tinned chickpeas"}, {"q": 1, "unit": "tbsp", "name": "olive oil"}, {"q": 1, "unit": "tsp", "name": "smoked paprika"}, {"q": 0.5, "unit": "tsp", "name": "ground cumin"}, {"q": 0.25, "unit": "tsp", "name": "salt"}], "steps": [{"title": "Dry thoroughly", "time": 10, "text": "Heat oven to 200°C fan / 220°C conventional. Rinse and drain chickpeas, then pat very dry with a clean towel."}, {"title": "Roast", "time": 30, "text": "Toss with oil and salt, spread in one layer on a metal tray and roast for 25–35 minutes. Shake the tray halfway; look for dry, lightly golden surfaces."}, {"title": "Season and cool", "time": 10, "text": "Toss hot chickpeas with paprika and cumin. Cool uncovered for 10 minutes; they firm as steam escapes. Eat the same day for the best crunch."}], "science": "Surface moisture must evaporate before chickpeas become crisp. Crowding the tray traps steam.", "fix": "Soft: dry more thoroughly and spread over two trays. Burnt spices: add them after roasting.", "lesson": "roasting", "equipment": "Oven, large metal tray, towel and bowl.", "tags": ["Easy", "Savoury", "Crispy", "Warm"], "foodTypes": []}, {"id": "red-lentil-soup", "title": "Lemon & cumin red lentil soup", "category": "Lunch", "prep": 10, "cook": 25, "rest": 0, "serves": 4, "ingredients": [{"q": 1, "unit": "tbsp", "name": "olive oil"}, {"q": 1, "unit": "", "name": "onion, diced"}, {"q": 1, "unit": "", "name": "carrot, diced"}, {"q": 2, "unit": "", "name": "garlic cloves, minced"}, {"q": 1, "unit": "tsp", "name": "ground cumin"}, {"q": 200, "unit": "g", "name": "red lentils, rinsed"}, {"q": 1000, "unit": "ml", "name": "vegetable stock"}, {"q": 2, "unit": "tbsp", "name": "lemon juice"}], "steps": [{"title": "Soften the base", "time": 8, "text": "Heat oil over medium heat in a large saucepan. Cook onion and carrot for 7–8 minutes, stirring, until softened."}, {"title": "Add flavour", "time": 1, "text": "Add garlic and cumin and stir for 30–60 seconds; do not let garlic turn dark."}, {"title": "Simmer", "time": 18, "text": "Add rinsed lentils and stock. Bring to a boil, then simmer gently for 15–20 minutes, stirring occasionally, until lentils collapse."}, {"title": "Finish", "time": 2, "text": "Mash with a potato masher for a thick soup or leave textured. Stir in lemon. Add hot water if needed and taste before adding salt."}], "science": "Split red lentils soften quickly and release starch, thickening the soup without flour.", "fix": "Too thick: add hot water or stock. Lentils still gritty: simmer longer, adding liquid as needed.", "lesson": "starch", "equipment": "Large saucepan, spoon, knife, board and optional potato masher.", "tags": ["Easy", "Savoury", "Warm"], "foodTypes": []}, {"id": "pea-lemon-pasta", "title": "Pea, lemon & cream-cheese pasta", "category": "Dinner", "prep": 10, "cook": 15, "rest": 0, "serves": 2, "ingredients": [{"q": 180, "unit": "g", "name": "dried pasta"}, {"q": 150, "unit": "g", "name": "frozen peas"}, {"q": 80, "unit": "g", "name": "cream cheese"}, {"q": 1, "unit": "tsp", "name": "finely grated lemon zest"}, {"q": 1, "unit": "tbsp", "name": "lemon juice"}, {"q": 20, "unit": "g", "name": "grated hard cheese"}, {"q": 1, "unit": "pinch", "name": "black pepper"}], "steps": [{"title": "Boil pasta", "time": 12, "text": "Bring a large pan of water to a boil. Cook pasta following its packet time, usually 9–12 minutes. Add peas for the final 3 minutes."}, {"title": "Reserve the water", "time": 1, "text": "Before draining, scoop out 200 ml cooking water into a heatproof jug."}, {"title": "Make the sauce", "time": 2, "text": "Return drained pasta and peas to the warm pan off the heat. Stir in cream cheese, zest, juice, hard cheese and 60 ml reserved water."}, {"title": "Adjust", "time": 1, "text": "Toss until glossy. Add reserved water a tablespoon at a time until the sauce coats the pasta. Season with pepper and serve immediately."}], "science": "Starchy pasta water helps the cheese and water form a cohesive sauce. Off-heat mixing reduces the chance of splitting.", "fix": "Claggy: add a little warm pasta water. Watery: toss for another minute before adding more liquid.", "lesson": "emulsions", "equipment": "Large saucepan, colander, heatproof jug and spoon.", "tags": ["Easy", "Creamy", "Warm"], "foodTypes": []}, {"id": "baked-feta-tomatoes", "title": "Roasted tomato & feta pasta", "category": "Dinner", "prep": 10, "cook": 30, "rest": 0, "serves": 3, "ingredients": [{"q": 500, "unit": "g", "name": "cherry tomatoes, washed"}, {"q": 150, "unit": "g", "name": "feta"}, {"q": 2, "unit": "tbsp", "name": "olive oil"}, {"q": 2, "unit": "", "name": "garlic cloves, peeled"}, {"q": 225, "unit": "g", "name": "dried pasta"}, {"q": 1, "unit": "tsp", "name": "dried oregano"}], "steps": [{"title": "Set up", "time": 10, "text": "Heat oven to 180°C fan / 200°C conventional. Put tomatoes and garlic in a baking dish. Place feta in the middle and add oil and oregano."}, {"title": "Roast", "time": 30, "text": "Roast for 25–30 minutes until tomatoes burst and feta softens. Stir tomatoes halfway without breaking up the feta."}, {"title": "Cook pasta", "time": 12, "text": "During the final 12 minutes, boil pasta to its packet time. Reserve 150 ml pasta water before draining."}, {"title": "Combine", "time": 2, "text": "Mash the roasted garlic, tomatoes and feta with a fork. Toss with pasta, adding reserved water in spoonfuls until saucy. Taste before adding salt: feta is already salty."}], "science": "Roasting removes some water from tomatoes and concentrates flavour. Starchy pasta water loosens the mashed feta into a sauce.", "fix": "Dry: add pasta water gradually. Too salty: use less feta next time and avoid salting before tasting.", "lesson": "roasting", "equipment": "Ovenproof baking dish, saucepan, colander and fork.", "tags": ["Easy", "Savoury", "Saucy", "Warm"], "foodTypes": []}, {"id": "butter-bean-skillet", "title": "Creamy tomato & butter-bean skillet", "category": "Dinner", "prep": 10, "cook": 20, "rest": 0, "serves": 3, "ingredients": [{"q": 1, "unit": "tbsp", "name": "olive oil"}, {"q": 1, "unit": "", "name": "onion, diced"}, {"q": 2, "unit": "", "name": "garlic cloves, minced"}, {"q": 400, "unit": "g", "name": "tinned chopped tomatoes"}, {"q": 480, "unit": "g", "name": "drained tinned butter beans"}, {"q": 100, "unit": "ml", "name": "water"}, {"q": 100, "unit": "g", "name": "spinach, washed"}, {"q": 60, "unit": "g", "name": "cream cheese"}], "steps": [{"title": "Soften onion", "time": 7, "text": "Warm oil in a wide pan over medium heat. Stir onion for 6–8 minutes until soft."}, {"title": "Build the sauce", "time": 10, "text": "Add garlic for 30 seconds, then tomatoes, beans and water. Simmer uncovered for 10 minutes, stirring gently."}, {"title": "Wilt spinach", "time": 2, "text": "Add spinach in handfuls and stir until wilted and the mixture is steaming hot throughout."}, {"title": "Finish gently", "time": 1, "text": "Take off the heat and stir in cream cheese. Mash a few beans against the side if you want a thicker sauce; taste and season."}], "science": "Mashing some beans releases starch and thickens the liquid. Adding cream cheese off the heat gives a smoother finish.", "fix": "Too thick: add water. Too sharp: simmer the tomatoes a little longer before adding cheese.", "lesson": "starch", "equipment": "Wide sauté pan, spoon, knife and board.", "tags": ["Easy", "Creamy", "Savoury", "Warm"], "foodTypes": []}, {"id": "mushroom-stroganoff", "title": "Paprika mushroom stroganoff", "category": "Dinner", "prep": 10, "cook": 20, "rest": 0, "serves": 2, "ingredients": [{"q": 350, "unit": "g", "name": "mushrooms, cleaned and sliced"}, {"q": 1, "unit": "tbsp", "name": "olive oil"}, {"q": 1, "unit": "", "name": "onion, sliced"}, {"q": 1, "unit": "tsp", "name": "smoked paprika"}, {"q": 1, "unit": "tsp", "name": "plain flour"}, {"q": 200, "unit": "ml", "name": "vegetable stock"}, {"q": 80, "unit": "g", "name": "soured cream"}, {"q": 1, "unit": "tsp", "name": "Dijon mustard"}], "steps": [{"title": "Brown mushrooms", "time": 9, "text": "Heat oil in a wide frying pan over medium-high heat. Cook mushrooms for 8–10 minutes until released water evaporates and edges brown; use batches if crowded."}, {"title": "Soften onion", "time": 6, "text": "Lower heat to medium, add onion and cook for 5–6 minutes, stirring."}, {"title": "Thicken", "time": 4, "text": "Stir in paprika and flour for 30 seconds. Gradually stir in stock and simmer for 3–4 minutes until lightly thickened."}, {"title": "Finish off heat", "time": 1, "text": "Remove from heat. Stir in soured cream and mustard. Serve with separately prepared rice, pasta or bread."}], "science": "Mushrooms need time to shed water before browning. Flour thickens the stock; avoiding a boil after adding soured cream helps prevent curdling.", "fix": "Pale mushrooms: let moisture evaporate before stirring constantly. Split sauce: remove heat and whisk in a little cool cream.", "lesson": "browning", "equipment": "Wide frying pan, spoon, knife and board.", "tags": ["Easy", "Creamy", "Savoury", "Warm"], "foodTypes": []}, {"id": "sweet-potato-wedges", "title": "Crisp-edged sweet potato wedges", "category": "Lunch", "prep": 10, "cook": 35, "rest": 0, "serves": 3, "ingredients": [{"q": 600, "unit": "g", "name": "sweet potatoes, washed"}, {"q": 1, "unit": "tbsp", "name": "cornflour"}, {"q": 1.5, "unit": "tbsp", "name": "olive oil"}, {"q": 1, "unit": "tsp", "name": "smoked paprika"}, {"q": 0.25, "unit": "tsp", "name": "salt"}], "steps": [{"title": "Cut evenly", "time": 10, "text": "Heat oven to 200°C fan / 220°C conventional. Cut potatoes into wedges about 2 cm thick; leave clean skins on."}, {"title": "Coat", "time": 2, "text": "Pat dry. Toss with cornflour, then oil, paprika and salt until lightly coated."}, {"title": "Roast", "time": 35, "text": "Arrange in a single layer with gaps on a metal tray. Roast 30–35 minutes, turning after 20 minutes, until tender inside with browned edges."}, {"title": "Serve", "time": 1, "text": "Serve promptly. Sweet potato wedges will have softer centres than ordinary chips; do not keep roasting until they are hard throughout."}], "science": "A thin starch coating helps dry and firm the surface. Spacing lets moisture escape instead of steaming neighbouring wedges.", "fix": "Soggy: use a larger tray. Burnt tips but firm middles: cut more evenly and lower the heat slightly.", "lesson": "roasting", "equipment": "Oven, metal baking tray, bowl, board and knife.", "tags": ["Easy", "Sweet", "Warm"], "foodTypes": []}, {"id": "lemon-couscous", "title": "Lemon, cucumber & chickpea couscous", "category": "Lunch", "prep": 15, "cook": 5, "rest": 5, "serves": 3, "ingredients": [{"q": 180, "unit": "g", "name": "instant couscous"}, {"q": 220, "unit": "ml", "name": "boiling vegetable stock"}, {"q": 240, "unit": "g", "name": "drained tinned chickpeas"}, {"q": 150, "unit": "g", "name": "cucumber, washed and diced"}, {"q": 150, "unit": "g", "name": "tomatoes, washed and diced"}, {"q": 2, "unit": "tbsp", "name": "olive oil"}, {"q": 2, "unit": "tbsp", "name": "lemon juice"}, {"q": 10, "unit": "g", "name": "fresh parsley, washed and chopped"}], "steps": [{"title": "Hydrate couscous", "time": 5, "text": "Put couscous in a heatproof bowl. Add boiling stock, cover and leave 5 minutes, or follow the packet ratio if different."}, {"title": "Prepare vegetables", "time": 10, "text": "Meanwhile dice cucumber and tomatoes and rinse and drain chickpeas. Whisk oil and lemon together."}, {"title": "Fluff", "time": 5, "text": "Uncover couscous and fluff with a fork. Spread slightly and let excess steam escape for 5 minutes."}, {"title": "Mix", "time": 2, "text": "Fold in chickpeas, vegetables, parsley and dressing. Taste for seasoning. Serve warm or cool and refrigerate promptly."}], "science": "Instant couscous absorbs hot liquid; fluffing separates the hydrated grains. Adding vegetables after steam subsides keeps their texture fresher.", "fix": "Clumped: fluff gently rather than pressing with a spoon. Wet: check the packet water ratio.", "lesson": "starch", "equipment": "Heatproof bowl with cover, fork, measuring jug and knife.", "tags": ["Easy", "Fresh", "Warm"], "foodTypes": []}, {"id": "french-toast", "title": "Vanilla cinnamon French toast", "category": "Breakfast", "prep": 8, "cook": 12, "rest": 0, "serves": 2, "ingredients": [{"q": 4, "unit": "slices", "name": "day-old bread"}, {"q": 2, "unit": "", "name": "medium eggs"}, {"q": 100, "unit": "ml", "name": "milk"}, {"q": 0.5, "unit": "tsp", "name": "vanilla extract"}, {"q": 0.5, "unit": "tsp", "name": "ground cinnamon"}, {"q": 15, "unit": "g", "name": "butter"}, {"q": 2, "unit": "tbsp", "name": "maple syrup"}], "steps": [{"title": "Mix the custard", "time": 3, "text": "Whisk eggs, milk, vanilla and cinnamon in a shallow dish until no egg-white streaks remain."}, {"title": "Dip", "time": 2, "text": "Dip each bread slice for about 10 seconds per side. It should absorb custard but still hold together."}, {"title": "Cook in batches", "time": 12, "text": "Melt half the butter in a non-stick pan over medium-low heat. Cook two slices for 3–4 minutes per side, until golden and the egg mixture is set through the centre. Repeat with remaining butter and bread."}, {"title": "Serve", "time": 1, "text": "Serve straight away with maple syrup. If the outside browns before the centre sets, lower the heat and give it longer."}], "science": "Day-old bread absorbs custard while holding its shape. Gentle heat gives egg proteins time to set before the outside burns.", "fix": "Soggy: shorten the soak or use firmer bread. Burnt: lower heat and wipe burnt butter from the pan between batches.", "lesson": "proteins", "equipment": "Shallow dish, whisk, non-stick frying pan and spatula.", "tags": ["Easy", "Sweet", "Warm"], "foodTypes": []}, {"id": "cheddar-scones", "title": "Cheddar & chive scones", "category": "Baking", "prep": 15, "cook": 15, "rest": 10, "serves": 8, "ingredients": [{"q": 225, "unit": "g", "name": "self-raising flour"}, {"q": 50, "unit": "g", "name": "cold butter, diced"}, {"q": 100, "unit": "g", "name": "cheddar, grated"}, {"q": 120, "unit": "ml", "name": "milk, plus a little to brush"}, {"q": 1, "unit": "tbsp", "name": "fresh chives, washed and chopped"}, {"q": 0.25, "unit": "tsp", "name": "salt"}], "steps": [{"title": "Prepare", "time": 5, "text": "Heat oven to 200°C fan / 220°C conventional. Line a baking tray. Mix flour and salt."}, {"title": "Rub and mix", "time": 7, "text": "Rub cold butter into flour with fingertips until like coarse crumbs. Stir in cheddar and chives. Add milk and stir just until a soft dough forms; use a splash more only if dry flour remains."}, {"title": "Shape", "time": 3, "text": "Pat dough 2.5 cm thick on a lightly floured surface. Cut eight roughly equal wedges without kneading. Set apart on the tray and brush tops with milk."}, {"title": "Bake and cool", "time": 15, "text": "Bake for 12–15 minutes until risen and golden, with set centres. Cool on a rack for 10 minutes. This batch makes eight scones; use the pieces quantity when scaling ingredients."}], "science": "Cold butter and minimal handling help keep the crumb tender. Overworking the dough develops gluten and makes the scones tougher.", "fix": "Flat: check flour freshness and keep dough thick. Tough: mix less and avoid repeated re-rolling.", "lesson": "gluten", "equipment": "Oven, lined tray, bowl, knife and cooling rack.", "tags": ["Moderate", "Savoury", "Warm"], "foodTypes": []}, {"id": "berry-oat-crumble", "title": "Berry & oat crumble", "category": "Dessert", "prep": 15, "cook": 30, "rest": 10, "serves": 4, "ingredients": [{"q": 500, "unit": "g", "name": "fresh mixed berries, washed and prepared"}, {"q": 40, "unit": "g", "name": "sugar for filling"}, {"q": 1, "unit": "tbsp", "name": "cornflour"}, {"q": 80, "unit": "g", "name": "plain flour"}, {"q": 50, "unit": "g", "name": "rolled oats"}, {"q": 60, "unit": "g", "name": "cold butter, diced"}, {"q": 40, "unit": "g", "name": "sugar for topping"}], "steps": [{"title": "Prepare filling", "time": 5, "text": "Heat oven to 180°C fan / 200°C conventional. Halve large strawberries. Mix berries with filling sugar and cornflour in a 20 cm baking dish."}, {"title": "Make crumble", "time": 10, "text": "Rub butter into plain flour until crumbly. Mix in oats and topping sugar; leave some larger clumps."}, {"title": "Bake", "time": 30, "text": "Scatter topping evenly over the berries. Bake for 25–35 minutes until golden and the filling bubbles at the edges."}, {"title": "Rest", "time": 10, "text": "Rest 10 minutes before spooning into bowls. The filling is very hot straight from the oven. Serve with yoghurt or separately prepared custard."}], "science": "Cornflour thickens the hot fruit juices. Resting lets the bubbling filling cool and become less runny.", "fix": "Powdery topping: rub butter through more evenly. Runny filling: ensure juices bubbled before taking it out.", "lesson": "starch", "equipment": "Oven, 20 cm baking dish, bowl, scales and spoon.", "tags": ["Easy", "Sweet", "Warm"], "foodTypes": []}, {"id": "lemon-yoghurt-cake", "title": "Lemon yoghurt loaf cake", "category": "Baking", "prep": 15, "cook": 50, "rest": 30, "serves": 8, "ingredients": [{"q": 175, "unit": "g", "name": "plain flour"}, {"q": 2, "unit": "tsp", "name": "baking powder"}, {"q": 150, "unit": "g", "name": "caster sugar"}, {"q": 2, "unit": "", "name": "medium eggs"}, {"q": 125, "unit": "g", "name": "plain yoghurt"}, {"q": 80, "unit": "ml", "name": "neutral cooking oil"}, {"q": 1, "unit": "tbsp", "name": "finely grated lemon zest"}, {"q": 2, "unit": "tbsp", "name": "lemon juice"}], "steps": [{"title": "Prepare tin", "time": 5, "text": "Heat oven to 160°C fan / 180°C conventional. Line a 900 g loaf tin with baking paper. Mix flour and baking powder in one bowl."}, {"title": "Mix wet ingredients", "time": 5, "text": "In another bowl whisk sugar, eggs, yoghurt, oil, lemon zest and juice until smooth."}, {"title": "Combine", "time": 5, "text": "Fold the dry mixture into the wet ingredients just until no dry flour remains. Pour into the tin and level gently; do not beat heavily."}, {"title": "Bake", "time": 50, "text": "Bake for 45–55 minutes until risen and a skewer inserted into the centre comes out without wet batter. If the top browns early, cover loosely with foil."}, {"title": "Cool", "time": 30, "text": "Leave in the tin for 10 minutes, then lift onto a rack. Cool at least 20 more minutes before slicing; the centre continues to firm as it cools."}], "science": "Baking powder produces gas that expands the batter. Folding only until combined limits gluten development, keeping the cake tender.", "fix": "Sunken centre: check it is baked through before removing. Dense crumb: avoid overmixing and check baking powder freshness.", "lesson": "leavening", "equipment": "Oven, lined 900 g loaf tin, two bowls, whisk, spatula, skewer and rack.", "tags": ["Moderate", "Sweet", "Warm"], "foodTypes": []}];
